import os
import json
import hashlib
import hmac
import struct
import asyncio
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding as sym_padding
from cryptography.hazmat.backends import default_backend

SERVER_KEY = os.urandom(32)
HMAC_KEY = os.urandom(32)

class ChatMessage:
    def __init__(self, sender, content, timestamp):
        self.sender = sender
        self.content = content
        self.timestamp = timestamp

class FileUploadProcessor:
    """Processes encrypted file uploads from chat clients."""

    def __init__(self, encryption_key, auth_key):
        self._enc_key = encryption_key
        self._auth_key = auth_key
        self._upload_dir = "/tmp/chat_uploads"
        os.makedirs(self._upload_dir, exist_ok=True)

    def _verify_integrity(self, data, received_mac):
        """Verify HMAC-SHA256 of the ciphertext."""
        computed = hmac.new(self._auth_key, data, hashlib.sha256).digest()
        return hmac.compare_digest(computed, received_mac)

    def _decrypt_payload(self, iv, ciphertext):
        """Decrypt AES-256-CBC ciphertext and remove PKCS7 padding."""
        cipher = Cipher(
            algorithms.AES(self._enc_key),
            modes.CBC(iv),
            backend=default_backend()
        )
        decryptor = cipher.decryptor()
        plaintext_padded = decryptor.update(ciphertext) + decryptor.finalize()

        unpadder = sym_padding.PKCS7(128).unpadder()
        plaintext = unpadder.update(plaintext_padded) + unpadder.finalize()
        return plaintext

    def process_upload(self, encrypted_bundle):
        """Process an encrypted file upload bundle.

        Format: [IV (16 bytes)][Ciphertext (N bytes)][HMAC-SHA256 (32 bytes)]
        """
        if len(encrypted_bundle) < 64:
            return {"status": "error", "code": "INVALID_LENGTH"}

        iv = encrypted_bundle[:16]
        received_mac = encrypted_bundle[-32:]
        ciphertext = encrypted_bundle[16:-32]

        if len(ciphertext) % 16 != 0:
            return {"status": "error", "code": "INVALID_CIPHERTEXT"}

        # Verify MAC over IV + ciphertext
        mac_data = iv + ciphertext
        if not self._verify_integrity(mac_data, received_mac):
            return {"status": "error", "code": "AUTH_FAILED"}

        try:
            plaintext = self._decrypt_payload(iv, ciphertext)
        except ValueError as e:
            return {"status": "error", "code": "PADDING_ERROR"}
        except Exception as e:
            return {"status": "error", "code": "DECRYPT_ERROR"}

        return {"status": "success", "data": plaintext}


class ChatServer:
    def __init__(self):
        self.processor = FileUploadProcessor(SERVER_KEY, HMAC_KEY)
        self.clients = {}
        self.message_history = []

    async def handle_client(self, reader, writer):
        addr = writer.get_extra_info('peername')
        client_id = f"{addr[0]}:{addr[1]}"
        self.clients[client_id] = writer

        try:
            while True:
                header = await reader.readexactly(4)
                msg_len = struct.unpack('>I', header)[0]

                if msg_len > 10 * 1024 * 1024:
                    await self._send_response(writer, {"error": "Message too large"})
                    continue

                data = await reader.readexactly(msg_len)
                await self._route_message(client_id, data, writer)
        except (asyncio.IncompleteReadError, ConnectionResetError):
            pass
        finally:
            del self.clients[client_id]
            writer.close()

    async def _route_message(self, client_id, data, writer):
        try:
            envelope = json.loads(data[:256])
        except (json.JSONDecodeError, UnicodeDecodeError):
            envelope = {"type": "upload"}

        if envelope.get("type") == "chat":
            msg = ChatMessage(client_id, envelope.get("content", ""), 
                            envelope.get("timestamp", 0))
            self.message_history.append(msg)
            await self._broadcast(msg)
        elif envelope.get("type") == "upload":
            result = self._handle_upload(data)
            await self._send_response(writer, result)
        elif envelope.get("type") == "rekey":
            await self._send_response(writer, {"status": "rekey_unsupported"})

    def _handle_upload(self, raw_data):
        """Extract binary payload and process encrypted upload."""
        # Find the binary payload after the JSON header
        separator_idx = raw_data.find(b'\x00')
        if separator_idx == -1:
            encrypted_bundle = raw_data
        else:
            encrypted_bundle = raw_data[separator_idx + 1:]

        return self.processor.process_upload(encrypted_bundle)

    async def _broadcast(self, msg):
        payload = json.dumps({
            "type": "chat",
            "sender": msg.sender,
            "content": msg.content,
            "timestamp": msg.timestamp
        }).encode()
        for cid, writer in list(self.clients.items()):
            try:
                writer.write(struct.pack('>I', len(payload)) + payload)
                await writer.drain()
            except Exception:
                pass

    async def _send_response(self, writer, response):
        payload = json.dumps(response).encode()
        writer.write(struct.pack('>I', len(payload)) + payload)
        await writer.drain()


async def main():
    server = ChatServer()
    srv = await asyncio.start_server(server.handle_client, '0.0.0.0', 8443)
    async with srv:
        await srv.serve_forever()

if __name__ == '__main__':
    asyncio.run(main())
